      kind: "if" | "each";
      path: string;
      truthy: Node[];
      falsy: Node[];
      location: Location;
    };

type BlockNode = Extract<Node, { type: "block" }>;

type Frame = {
  block: BlockNode;
  children: Node[];
  hasElse: boolean;
};

type Scope = {
  value: unknown;
  index: number;
};

